        h = 31 * h + b.mTotalRows;
        h = 31 * h + b.getActiveTranscriptRows();
        for (int row = -b.getActiveTranscriptRows(); row < b.mScreenRows; row++) {
            TerminalRow line = b.mLines[b.externalToInternalRow(row)];
